export const findSumPairs = (array: number[], targetSum: number) => {
  const hash: Record<string, number> = {};

  for (let index = 0; index < array.length; index++) {
    // 4
    const pair1 = array[index];

    // 12 - 4 = 8
    const pair2 = targetSum - pair1;

    if (hash[pair2]) {
      return [pair2, pair1];
    }

    // 12 = { 4 : 8 }
    hash[pair1] = pair2;
  }

  return [];
};

