console.log(range([1, 4, 3, 2])); // "1-4"
console.log(range([10, 12, 11, 14, 15, 16])); // "10-12,14-16"
console.log(range([])); // ""
console.log(range([1, 2, 2, 3, 4, 6, 7, 9])); // "1-4,6-7,9"
console.log(range([1, 3, 5, 7, 9])); // "1,3,5,7,9"

