tasks.solution:
export function* factorial(n: number): Generator<number> {
  if (n === 0) {
    yield 1;
    return;
  }
  let ans = 1;
  for (let i = 1; i <= n; ++i) {
    ans *= i;
    yield ans;
  }
}

