export function sumIntervals(intervals: [number, number][]) {
  const sorted = intervals.sort((a, b) => a[0] - b[0]);
  let max = 0;
  let res = 0;

  for (let i = 0; i < sorted.length; i++) {
    const [left, right] = sorted[i];
    if (left > max) {
      res += right - left;
    } else if (right > max) {
      res += right - max;
    }
    max = Math.max(right, max);
  }
  return res;
}

// prettier-ignore
