intersection(
  [[8, 12], [17, 22]],
  [[5, 11], [14, 18], [20, 23]]
) // => [[8, 11], [17, 18], [20, 22]]

// prettier-ignore
intersection(
  [[9, 15], [18, 21]],
  [[10, 14], [21, 22]]
) // => [[10, 14]]

