proto.solution:
Array.prototype.forEach = function (
  callback: (value: any, index: number, array: any[]) => void,
  context?: any
): void {
  for (let i = 0; i < this.length; ++i) {
    callback.call(context, this[i], i, this);
  }
};

export {};

