ts.solution:
export function cleanObject<T extends object>(
  obj: T
): { [K in keyof T as T[K] extends null | undefined ? never : K]: T[K] } {
  return Object.fromEntries(
    Object.entries(obj).filter(([, value]) => value !== null && value !== undefined)
  ) as any;
}

