  MyExtract,
  MyReturnType,
  MyInstanceType,
} from "../solution";

test("MyRecord", () => {
  expectTypeOf<MyRecord<"a" | "b", number>>().toEqualTypeOf<{ a: number; b: number }>();
});

test("MyOmit", () => {
