});

test("MyPartial", () => {
  expectTypeOf<MyPartial<{ a: number; b: string }>>().toEqualTypeOf<{ a?: number; b?: string }>();
});

test("MyRequired", () => {
  expectTypeOf<MyRequired<{ a?: number; b?: string }>>().toEqualTypeOf<{ a: number; b: string }>();
});

test("MyReadonly", () => {
